const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:900},reducedMotion:'no-preference'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.click('#learningTab');if(await p.locator('#learningView [data-motion-toggle],#learningView #sfxToggle,.profile-bar #sfxToggle').count())throw Error('Settings leaked outside options');if(await p.locator('#optionsDialog[open]').count())throw Error('Settings open on load');
await p.click('#optionsButton');if(!await p.locator('#optionsDialog[open]').count()||!await p.locator('#sfxToggle').isVisible()||!await p.locator('[data-motion-toggle]').isVisible())throw Error('Settings not in dialog');await p.click('#sfxToggle');await p.click('[data-motion-toggle]');if(await p.locator('#sfxToggle').getAttribute('aria-pressed')!=='false'||await p.locator('#learningView').getAttribute('data-motion')!=='off')throw Error('Setting did not apply');await p.keyboard.press('Escape');if(await p.locator('#optionsDialog[open]').count()||!await p.locator('#optionsButton').evaluate(e=>e===document.activeElement))throw Error('Escape/focus return');
await p.reload();await p.click('#optionsButton');if(await p.locator('#sfxToggle').getAttribute('aria-pressed')!=='false'||await p.locator('[data-motion-toggle]').getAttribute('aria-pressed')!=='false')throw Error('Existing profile preferences lost');await p.click('[data-motion-toggle]');await p.emulateMedia({reducedMotion:'reduce'});await p.waitForFunction(()=>document.querySelector('[data-motion-toggle]').disabled&&document.querySelector('#learningView').dataset.motion==='off');if(!await p.locator('[data-motion-toggle]').isDisabled()||!await p.locator('#optionsReducedMotion').isVisible()||await p.locator('#learningView').getAttribute('data-motion')!=='off')throw Error('System reduced motion ignored');
for(const width of [320,390,1280]){await p.setViewportSize({width,height:900});if(await p.locator('#optionsDialog').evaluate(e=>e.getBoundingClientRect().width>innerWidth)||await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Settings overflow '+width)}await p.evaluate(()=>document.documentElement.lang='en');await p.waitForFunction(()=>document.querySelector('#optionsTitle').textContent==='Options');await p.click('#optionsClose');await p.click('#wordsTab');await p.click('#optionsButton');if(!await p.locator('#optionsDialog[open]').count())throw Error('Options unavailable outside map');await p.click('#optionsClose');if(errors.length)throw Error(errors.join(';'));console.log('PASS Options: clean map/header, real sound and motion controls, immediate application, persistence, system reduced motion, Escape/focus, responsive modal, localization and access from other screens');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
